49:/** Pure time conversion: convert local date and time in an IANA time zone to UTC epoch ms. */
50:export const localToUtc = (
51:  year: number,
52:  month: number,
53:  day: number,
54:  hour: number,
55:  minute: number,
56:  timeZone: string,
57:): number => {
58:  const targetLocalAsUtc = Date.UTC(year, month - 1, day, hour, minute, 0);
59:
60:  const getLocal = (utcMs: number) => {
61:    const dtf = new Intl.DateTimeFormat("en-US", {
62:      timeZone,
63:      year: "numeric",
64:      month: "2-digit",
65:      day: "2-digit",
66:      hour: "2-digit",
67:      minute: "2-digit",
68:      second: "2-digit",
69:      hour12: false,
70:    });
71:    const parts: Record<string, string> = {};
72:    for (const p of dtf.formatToParts(new Date(utcMs))) {
73:      parts[p.type] = p.value;
74:    }
75:    let h = parseInt(parts.hour ?? "0", 10);
76:    if (h === 24) h = 0;
77:    return {
78:      year: parseInt(parts.year ?? "0", 10),
79:      month: parseInt(parts.month ?? "0", 10),
80:      day: parseInt(parts.day ?? "0", 10),
81:      hour: h,
82:      minute: parseInt(parts.minute ?? "0", 10),
83:    };
84:  };
85:
86:  const toAsUtc = (l: { year: number; month: number; day: number; hour: number; minute: number }) =>
87:    Date.UTC(l.year, l.month - 1, l.day, l.hour, l.minute, 0);
88:
89:  const dayBeforeUtc = targetLocalAsUtc - 86_400_000;
90:  const dayAfterUtc = targetLocalAsUtc + 86_400_000;
91:  const offsetBefore = toAsUtc(getLocal(dayBeforeUtc)) - dayBeforeUtc;
92:  const offsetAfter = toAsUtc(getLocal(dayAfterUtc)) - dayAfterUtc;
93:
94:  // In an overlap, earlier UTC instant wins (so larger offset first).
95:  const offsets = [offsetBefore, offsetAfter].sort((a, b) => b - a);
96:
97:  for (const offset of offsets) {
98:    const candidateUtc = targetLocalAsUtc - offset;
99:    if (toAsUtc(getLocal(candidateUtc)) === targetLocalAsUtc) {
100:      return candidateUtc;
101:    }
102:  }
103:
104:  // Spring-forward gap: time moves forward by the gap.
105:  const gap = Math.abs(offsetAfter - offsetBefore);
106:  const adjustedTargetAsUtc = targetLocalAsUtc + gap;
107:  return adjustedTargetAsUtc - offsetAfter;
108:};
