139: * Returns the next date (YYYY-MM-DD) matching `weekday` on or strictly after the given calendar date.
140: */
141:export const nextWeekdayDate = (
142:  fromYear: number,
143:  fromMonth: number,
144:  fromDay: number,
145:  targetWeekday: Weekday,
146:  includeToday: boolean,
147:): string => {
148:  const date = new Date(Date.UTC(fromYear, fromMonth - 1, fromDay));
149:  const currentWeekday = date.getUTCDay();
150:  const targetDayNum = WEEKDAY_NUMBERS[targetWeekday];
151:
152:  let daysAhead = targetDayNum - currentWeekday;
153:  if (daysAhead < 0 || (daysAhead === 0 && !includeToday)) {
154:    daysAhead += 7;
