CREATE TABLE schedule_job_new (
  id TEXT NOT NULL PRIMARY KEY,
  round_id TEXT NOT NULL REFERENCES round (id),
  type TEXT NOT NULL CHECK (type IN ('open', 'close', 'compute', 'send', 'remind', 'themes')),
  due_at INTEGER NOT NULL,
